1: /** Three consumer-private audience examples. Exposure is not a security sandbox. */
2: import type { Graph } from "../../packages/ts/src/graph/graph.js";
3: import {
4: 	assertCausalCapabilities,
5: 	type CausalBinding,
6: 	type FullCausalCapability,
7: } from "../../packages/ts/src/solutions/causal-occurrence/capabilities.js";
8: import type { SpendingAlertsView } from "./causal-preset.js";
9: import type { Publication } from "./causal-publication.js";
10: import { mountSpendingView } from "./causal-view-binding.js";
11: /** A display component receives only the actual five-port object. Subscription is observation. */
12: export function ordinaryExample(view: SpendingAlertsView, render: (value: Publication) => void) {
13: 	return mountSpendingView(view, ({ values }) => {
14: 		if (values.publication) render(values.publication);
15: 	});
16: }
17: /** Frameworks pass exact issued handles; an execution view grants no I/O method. */
18: export function frameworkExample<T>(
19: 	graph: Graph,
20: 	capabilities: FullCausalCapability<T>,
21: 	binding: CausalBinding,
22: ) {
23: 	assertCausalCapabilities(graph, capabilities, binding);
24: 	return capabilities.execution;
25: }
26: /** The maintainer still inspects the complete executing graph. */
27: export function maintainerExample(graph: Graph) {
28: 	return graph.describe();
29: }
30: function compileOnly(view: SpendingAlertsView) {
31: 	// @ts-expect-error Ordinary view has no internal authority capability.
32: 	view.capabilities;
33: 	// @ts-expect-error No imperative publication command.
34: 	view.publish();
35: 	// @ts-expect-error Eight input lanes are not component responsibilities.
36: 	view.effectAdmissions;
37: }
38: void compileOnly;
