53: export function causalBinding(binding: CausalBinding): CausalBinding {
54: 	if (
55: 		binding.contract !== "contract-v2" ||
56: 		binding.implementationRevision !== "construction-v1" ||
57: 		binding.scope !== "full" ||
58: 		!Number.isSafeInteger(binding.epoch) ||
59: 		binding.epoch < 1 ||
60: 		Object.keys(binding).length !== 4
61: 	)
62: 		throw new TypeError("unsupported causal binding or lifecycle epoch");
63: 	return Object.freeze({ ...binding });
