67: export function assertCausalCapabilities<T>(
68: 	graph: Graph,
69: 	full: FullCausalCapability<T>,
70: 	binding: CausalBinding,
71: ): void {
72: 	const root = issued.get(full);
73: 	if (
74: 		root === undefined ||
75: 		root.graph !== graph ||
76: 		root.level !== "full" ||
77: 		root.binding.contract !== binding.contract ||
78: 		root.binding.implementationRevision !== binding.implementationRevision ||
79: 		root.binding.scope !== binding.scope ||
80: 		root.binding.epoch !== binding.epoch"},{"ok":true,"content":"packages/ts/src/solutions/causal-occurrence/capabilities.ts
81: 	)
82: 		throw new TypeError("causal capability binding mismatch");
83: 	for (const handle of [full.identity, full.execution, full.retained]) {
84: 		const record = issued.get(handle);
85: 		if (record === undefined || record.instance !== root.instance || record.graph !== graph)
86: 			throw new TypeError("causal capability lineage mismatch");
87: 	}
88: 	if (full.execution.identity !== full.identity || full.retained.execution !== full.execution)
