99: 	const causalQuiescence = scope.node<Omit<CausalQuiescence, "retainedEvidence">>(
100: 		[ports.quiescence],
101: 		(ctx) => {
102: 			for (const raw of depBatch(ctx, 0) ?? []) {
103: 				const value = raw as CausalQuiescence;
104: 				// Explicit payload projection, not a type cast over retained evidence.
105: 				ctx.down([
106: 					[
107: 						"DATA",
108: 						Object.freeze({
109: 							kind: value.kind,
110: 							revisionDomain: value.revisionDomain,
111: 							evaluatedThroughRevision: value.evaluatedThroughRevision,
112: 							lifecycle: value.lifecycle,
113: 							pendingOccurrenceRefs: value.pendingOccurrenceRefs,
114: 							pendingEffectIds: value.pendingEffectIds,
115: 						}),
116: 					],
117: 				]);
118: 			}
119: 		},
120: 		{ name: `${name}/causal-quiescence`, factory: "causalLifecycleQuiescence" },
121: 	);
122: 	const identity = Object.freeze({
123: 		released: ports.released,
124: 		currentness: ports.currentness,
125: 		issues: ports.issues,
126: 	});
