134: 		execution,
135: 		coverage: ports.coverage,
136: 		retainedQuiescence: ports.quiescence,
137: 	});
138: 	const full = Object.freeze({ identity, execution, retained, startup: ports.startup });
139: 	const instance = Object.freeze({});
140: 	for (const [level, handle] of [
141: 		["identity", identity],
142: 		["execution", execution],
143: 		["retained", retained],
144: 		["full", full],
145: 	] as const)
146: 		issued.set(handle, { graph, instance, binding, level });
147: 	return full;
148: }
